        Point a, b, p;
        cin >> a.x >> a.y >> b.x >> b.y >> p.x >> p.y;
        if (a == b) cout << "DEGENERATE ";
        else cout << lineDistance(a, b, p) << ' ';
        cout << segmentDistance(a, b, p) << '\n';
    }
}

