    if (n < 3 || area2 == 0) cout << "DEGENERATE\n";
    else {
        i128 interior = (area2 - boundary + 2) / 2;
        cout << decimal(area2) << ' ' << decimal(interior) << ' ' << boundary << '\n';
    }
}

